// Isolated interactive fixture. No real NAS requests or authentication credentials.
import {mountTagEditor} from './tag-editor-host.js';
const names=['Alone Together','How High the Moon','It Never Entered My Mind','My Funny Valentine','September Song','You and the Night and the Music','If You Could See Me Now','Early Morning Mood'];
const definitions=[['11111111-1111-4111-8111-111111111111','Chet Baker','Chet','1959','POP & ROCK/Chet Baker/01. Albums/Chet'],['22222222-2222-4222-8222-222222222222','Chet Baker','Strollin’','1985','POP & ROCK/Chet Baker/01. Albums/Strollin'],['33333333-3333-4333-8333-333333333333','Chet Baker','As Time Goes By','1990','POP & ROCK/Chet Baker/01. Albums/As Time Goes By'],['44444444-4444-4444-8444-444444444444','데모 A\\데모 B','Together','2021','KPOP/데모 A\\데모 B/02. Single／Mini/Together']];
const records=definitions.map(([id,artist,title,year,path],i)=>({id,artist,title,original_year:year,relative_path:path,physical_files:(i===3?['우리의 노래','함께']:names.slice(0,i===1?5:8)).map((name,j)=>({path:path+'/'+(i===1?'CD'+(j<3?'1':'2')+'/':'')+(i===3?'1-':'')+String(j+1).padStart(2,'0')+' '+name+'.flac',size:25000000+j,mtime_ns:1234+j,raw_tags:{TITLE:j===2?[]:[name],ARTIST:[artist],ALBUMARTIST:[artist],ALBUM:[title],DATE:[year],TRACKNUMBER:j===2?[]:[String(i===1&&j>=3?j-2:j+1)],DISCNUMBER:[String(i===1&&j>=3?2:1)],GENRE:j%2?['Jazz','Cool Jazz']:[],FEATURING:j===3?['Enrico Pieranunzi','Philip Catherine']:[]}}))}));
window.previewRequests=[];window.previewErrors=[];let permission=true;
const image='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=';
async function demoApi(path,options={}){const began=performance.now(),u=new URL(path,location.origin);window.previewRequests.push({path,began,body:!!options.body});await new Promise(r=>setTimeout(r,u.pathname==='/v2/admin-album'?60:20));
 if(u.pathname==='/v2/folders'){const parent=u.searchParams.get('path')||'',prefix=parent?parent+'/':'';const paths=[...new Set(records.filter(a=>a.relative_path.startsWith(prefix)).map(a=>a.relative_path.slice(prefix.length).split('/')[0]).filter(Boolean))];return {folders:paths.map(name=>({name,path:prefix+name}))};}
 if(u.pathname==='/v2/albums'){const q=(u.searchParams.get('q')||'').toLowerCase();if(u.searchParams.get('view')==='artists')return {pages:1,items:[...new Set(records.map(a=>a.artist))].filter(a=>a.toLowerCase().includes(q)).map(name=>({name,count:records.filter(a=>a.artist===name).length}))};return {pages:1,items:records.filter(a=>(!q||(a.artist+' '+a.title+' '+a.relative_path).toLowerCase().includes(q))&&(!u.searchParams.get('artist')||a.artist===u.searchParams.get('artist'))).map(({physical_files,...a})=>a)};}
 if(u.pathname==='/v2/admin-album')return structuredClone(records.find(a=>a.id===u.searchParams.get('id')));
 if(u.pathname==='/v2/admin/tag-cover/inspect')return {state:'EMBEDDED_COVER_INSPECTED',file_sha256:'a'.repeat(64),catalog_digest:'b'.repeat(64),front_covers:[],other_cover_count:0};
 if(u.pathname==='/v2/admin/tag-cover/plan')return {state:'READ_ONLY_COVER_PLAN',plan_id:'DEMO_PLAN_NOT_PERSISTED',apply_supported:false,writer_enabled:false};
 throw Error('Preview only: unexpected route '+u.pathname);
}
const editor=mountTagEditor({container:document.querySelector('#previewEditor'),api:demoApi,canManage:()=>permission,preview:true,loadCover:async(img,id)=>{const colors={'11111111-1111-4111-8111-111111111111':['#8c6552','#ead4b2'],'22222222-2222-4222-8222-222222222222':['#334f65','#b7c8c7'],'33333333-3333-4333-8333-333333333333':['#695946','#cec5ad']},[bg,fg]=colors[id]||['#40635c','#d2e3dc'];const canvas=document.createElement('canvas');canvas.width=300;canvas.height=300;const c=canvas.getContext('2d');c.fillStyle=bg;c.fillRect(0,0,300,300);c.fillStyle=fg;c.font='24px serif';c.fillText('CHET BAKER',24,52);c.beginPath();c.arc(210,200,135,0,Math.PI*2);c.fill();c.fillStyle=bg;c.font='italic 62px serif';c.fillText('Chet',58,210);img.src=canvas.toDataURL();}});
window.previewEditor=editor;window.addEventListener('error',e=>window.previewErrors.push(e.message));

const mobileButton=document.querySelector('#mobilePreview');mobileButton.onclick=()=>{const host=document.querySelector('#previewEditor'),mobile=!host.style.maxWidth;host.style.maxWidth=mobile?'390px':'';host.style.margin='0 auto';mobileButton.textContent=mobile?'PC 보기':'모바일 보기';};
